import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
const pages=await(await fetch('http://127.0.0.1:9222/json')).json();
const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
let sequence=0;const pending=new Map(),errors=[],failed=[];
ws.onmessage=({data})=>{const m=JSON.parse(data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails);if(m.method==='Network.responseReceived'&&m.params.response.status>=400&&!m.params.response.url.endsWith('/favicon.ico'))failed.push(m.params.response.url);if(pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++sequence,{resolve,reject});ws.send(JSON.stringify({id:sequence,method,params}));});
const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
const output='docs/diario-ia/qa-resultados/arena-defesa';await fs.mkdir(output,{recursive:true});
try {
 await send('Page.enable');await send('Runtime.enable');await send('Network.enable');
 for(const [width,height]of [[390,844],[844,390]]) {
  await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:true});await send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:5});await send('Emulation.setUserAgentOverride',{userAgent:'Mozilla/5.0 (Linux; Android 14) Mobile'});
  await send('Page.navigate',{url:'http://127.0.0.1:3001/tests/toy-room-arena.html'});
  let ready=false;for(let i=0;i<200;i++){if(await evaluate('document.body?.dataset.ready==="true"')){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready);
  const controls=await evaluate(`(async()=>{arenaTest.pause();document.querySelector('nav').remove();document.querySelector('#status').remove();const r=arenaTest.room;const {runToyRoomQA}=await import('/tests/toy-room-qa-runner.js');runToyRoomQA(r,{draw:false});while(r.battle.state.transition)r.update();r.keysDown={};r.clearInput();r.render();const {getMobileUILayout,arenaMobileControlsLayout}=await import('/src/js/ui/MobileUILayout.js');const c=arenaMobileControlsLayout(getMobileUILayout(r.canvas));const rect=r.canvas.getBoundingClientRect();const point=(x,y)=>({x:rect.left+x*rect.width/r.canvas.width,y:rect.top+y*rect.height/r.canvas.height});const side=r.battle.state.enemy.x>r.player.x?1:-1;return {back:point(c.dpad.x-side*50*c.unit,c.dpad.y),forwardJump:point(c.dpad.x+side*50*c.unit,c.dpad.y-50*c.unit),sword:point(c.sword.x,c.sword.y),side};})()`);
  const touch=(type,points)=>send('Input.dispatchTouchEvent',{type,touchPoints:points.map(([id,p])=>({id,x:p.x,y:p.y,radiusX:5,radiusY:5,force:1}))});
  await touch('touchStart',[[1,controls.back]]);
  const guard=await evaluate(`(()=>{const r=arenaTest.room;for(let i=0;i<12;i++)r.update();r.render();return {guarding:r.battle.state.guarding,amount:r.battle.state.playerAnimation.guardAmount,facing:r.player.facing,buttons:r.arenaTouchButtons};})()`);
  assert.equal(guard.guarding,true,'Toque real para trás ativa defesa');assert.equal(guard.amount,1);assert.equal(guard.facing,controls.side>0?'right':'left');
  let shot=await send('Page.captureScreenshot',{format:'png'});await fs.writeFile(output+`/${width}-defesa.png`,Buffer.from(shot.data,'base64'));await fs.writeFile(`/tmp/legendgirl-${width}-defesa.png`,Buffer.from(shot.data,'base64'));
  await touch('touchMove',[[1,controls.forwardJump]]);
  const jump=await evaluate(`(()=>{const r=arenaTest.room;r.update();r.render();return {jump:r.battle.state.jump,x:r.battle.input().x,up:r.arenaTouchButtons.up,guarding:r.battle.state.guarding};})()`);assert.ok(jump.jump>0&&jump.up&&Math.sign(jump.x)===controls.side);assert.equal(jump.guarding,false);
  await touch('touchStart',[[1,controls.forwardJump],[2,controls.sword]]);
  assert.ok(await evaluate('arenaTest.room.battle.state.cooldown>0'),'Segundo dedo aciona espada durante salto diagonal');
  await touch('touchEnd',[]);assert.equal(await evaluate('Object.values(arenaTest.room.arenaTouchButtons).some(Boolean)'),false,'Fim do toque solta controles');
  const r=await evaluate(`(async()=>{const r=arenaTest.room;const {sampleArenaPlayerAnimation}=await import('/src/js/toy-room/ArenaPlayerAnimation.js');const {ArenaPlayerRenderer}=await import('/src/js/toy-room/ArenaPlayerRenderer.js');const renderer=new ArenaPlayerRenderer();await renderer.load();const canvas=document.createElement('canvas');canvas.width=900;canvas.height=280;const ctx=canvas.getContext('2d');ctx.fillStyle='#44354c';ctx.fillRect(0,0,900,280);const state={mode:'BATTLE',jump:0,jumpVelocity:0,playerHitTime:0,crouching:false,attackTime:0,guarding:true,playerAnimation:{pose:'guard',poseTime:12,time:12,previousPose:'guard',previousTime:12,blendTime:8,attackAge:36,attackSerial:0,attackDirection:1,guardAmount:1}};for(const [x,amount,facing]of [[130,0,'right'],[350,.5,'right'],[570,1,'right'],[790,1,'left']]){state.playerAnimation.guardAmount=amount;renderer.render(ctx,{player:{x,facing}},state,250);}return canvas.toDataURL().split(',')[1];})()`);await fs.writeFile(output+`/${width}-poses.png`,Buffer.from(r,'base64'));await fs.writeFile('/tmp/legendgirl-defesa-poses.png',Buffer.from(r,'base64'));
  await fs.writeFile(output+`/${width}.json`,JSON.stringify({width,height,guard,jump},null,2));console.log('APROVADO: toque real, defesa, arraste diagonal, salto e espada simultâneos em '+width+'×'+height);
 }
 assert.deepEqual(errors,[]);assert.deepEqual(failed,[]);
}finally{ws.close();}
